mapper.select:
select t.BID_ID bidId, t.ENTRUST_ID entrustId, m.ENTRUST_DATE bidDate, m.FINPROD_ID finprodId, m.TRADE_MARKET tradeMarket, CASE when y.PAY_TYPE is null then n.PAY_TYPE else y.PAY_TYPE end as payType, y.PAY_DATE payDate, y.IS_WIN isWin, y.WIN_PRIN_AMT, y.WIN_PRICE * 100 winPrice, y.WIN_TYPE, y.REMARK, s.FINPROD_ABBR finprodAbbr, s.FINPROD_MARKET_ID finprodMarketId, m.COUNTER_ID counterId from (select BID_ID,ENTRUST_ID from BID_ORDER_BID_PRICE
BID_ID = #{bidId} and ROWNUM<=1
) t inner join ETR_ENTRUST m on t.ENTRUST_ID=m.ENTRUST_ID inner join BID_ORDER y on t.BID_ID=y.BID_ID left join ETR_ENTRUST_ADD n on m.ENTRUST_ID=n.ENTRUST_ID left join FIN_PRODUCT s on m.FINPROD_ID=s.FINPROD_ID
